import math

def add_noise(x0, alpha_bar, eps):
    return math.sqrt(alpha_bar) * x0 + math.sqrt(1 - alpha_bar) * eps

def estimate_x0(xt, alpha_bar, eps_pred):
    if alpha_bar <= 0:
        raise ValueError('alpha_bar must be positive')
    return (xt - math.sqrt(1 - alpha_bar) * eps_pred) / math.sqrt(alpha_bar)

