def regression_report(baseline, candidate, tolerance):
    regressed, improved, missing = [], [], []
    for p, b in baseline.items():
        if p not in candidate:
            missing.append(p)
        elif candidate[p] < b - tolerance:
            regressed.append(p)
        elif candidate[p] > b + tolerance:
            improved.append(p)
    return {
        'regressed': sorted(regressed),
        'improved': sorted(improved),
        'missing': sorted(missing),
        'passed': not regressed and not missing,
    }

tests.code:
b = {'fox': 0.30, 'cats': 0.29, 'car': 0.25}
c = {'fox': 0.35, 'cats': 0.22, 'car': 0.26}
r = regression_report(b, c, 0.02)
assert r.get('regressed') == ['cats'] and r.get('improved') == ['fox'], f'got {r}'
assert r.get('passed') is False
